import 'package:flutter/material.dart';\r\nimport '../../core/theme/app_colors.dart';\r\nimport 'admin_management_screen.dart';\r\n\r\n/// Main scaffold for the admin role with bottom navigation.\r\n///\r\n/// Tabs: Management, Reports\r\n/// Per PRD §5.2 — the admin network-level management experience.\r\nclass AdminMainScaffold extends StatefulWidget {\r\n  const AdminMainScaffold({super.key});\r\n\r\n  @override\r\n  State<AdminMainScaffold> createState() => _AdminMainScaffoldState();\r\n}\r\n\r\nclass _AdminMainScaffoldState extends State<AdminMainScaffold> {\r\n  int _currentIndex = 0;\r\n\r\n  final List<Widget> _pages = [\r\n    const AdminManagementScreen(),\r\n    const Center(\r\n      child: Column(\r\n        mainAxisAlignment: MainAxisAlignment.center,\r\n        children: [\r\n          Icon(Icons.analytics_outlined, size: 64, color: Colors.grey),\r\n          SizedBox(height: 16),\r\n          Text('Reports Coming Soon',\r\n              style: TextStyle(fontSize: 18, color: Colors.grey)),\r\n        ],\r\n      ),\r\n    ),\r\n  ];\r\n\r\n  @override\r\n  Widget build(BuildContext context) {\r\n    return Scaffold(\r\n      body: IndexedStack(\r\n        index: _currentIndex,\r\n        children: _pages,\r\n      ),\r\n      bottomNavigationBar: NavigationBar(\r\n        selectedIndex: _currentIndex,\r\n        onDestinationSelected: (index) {\r\n          setState(() => _currentIndex = index);\r\n        },\r\n        destinations: const [\r\n          NavigationDestination(\r\n            icon: Icon(Icons.settings_outlined),\r\n            selectedIcon: Icon(Icons.settings),\r\n            label: 'Management',\r\n          ),\r\n          NavigationDestination(\r\n            icon: Icon(Icons.analytics_outlined),\r\n            selectedIcon: Icon(Icons.analytics),\r\n            label: 'Reports',\r\n          ),\r\n        ],\r\n      ),\r\n    );\r\n  }\r\n}\r\n
